import React, { useState, useEffect } from 'react';
import { getAllRestaurants } from '../../services/api';
import { useNavigate } from 'react-router-dom';

const RestaurantList = () => {
  const [restaurants, setRestaurants] = useState([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const navigate = useNavigate();

  useEffect(() => {
    loadRestaurants();
    const interval = setInterval(loadRestaurants, 10000);
    return () => clearInterval(interval);
  }, []);

  const loadRestaurants = async () => {
    try {
      const response = await getAllRestaurants();
      setRestaurants(response.data);
    } catch (error) {
      console.error('Error loading restaurants:', error);
    } finally {
      setLoading(false);
    }
  };

  const filteredRestaurants = restaurants.filter(r =>
    r.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    r.cuisine_type?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    r.address.toLowerCase().includes(searchTerm.toLowerCase())
  );

  if (loading) return <Loading />;

  return (
    <div style={styles.container}>
      <header style={styles.header}>
        <h1 style={styles.title}>Discover & Reserve</h1>
        <p style={styles.subtitle}>Book your favorite dining spots effortlessly</p>
        <div style={styles.searchContainer}>
          <input
            type="text"
            placeholder="Search by name, cuisine, or location..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            style={styles.searchInput}
          />
          {searchTerm && <button onClick={() => setSearchTerm('')} style={styles.clearBtn}>✕</button>}
        </div>
      </header>

      {filteredRestaurants.length === 0 ? (
        <EmptyState searchTerm={searchTerm} />
      ) : (
        <div style={styles.cardList}>
          {filteredRestaurants.map(r => (
            <div
              key={r.id}
              style={styles.card}
              onClick={() => navigate(`/restaurant/${r.id}`)}
              onMouseEnter={e => e.currentTarget.style.transform = 'translateY(-6px)'}
              onMouseLeave={e => e.currentTarget.style.transform = 'translateY(0)'}
            >
              <div style={{ ...styles.imageContainer, backgroundImage: `url(${r.image_url || 'https://via.placeholder.com/300x200?text=Food'})` }}>
                <div style={styles.ratingBadge}>⭐ 4.8</div>
              </div>
              <div style={styles.cardContent}>
                <h3 style={styles.restaurantName}>{r.name}</h3>
                <p style={styles.cuisine}>{r.cuisine_type}</p>
                <p style={styles.address}>📍 {r.address.split(',')[0]}</p>
                <p style={styles.hours}>🕒 {r.opening_time} - {r.closing_time}</p>
                <button style={styles.reserveBtn}>Reserve →</button>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

const Loading = () => (
  <div style={styles.loadingContainer}>
    <div style={styles.spinner}></div>
    <p style={styles.loadingText}>Loading restaurants...</p>
  </div>
);

const EmptyState = ({ searchTerm }) => (
  <div style={styles.emptyState}>
    <span style={styles.emptyIcon}>🍽️</span>
    <h2 style={styles.emptyTitle}>No restaurants found</h2>
    <p style={styles.emptyText}>
      {searchTerm ? 'Try a different search term' : 'Check back soon for new restaurants!'}
    </p>
  </div>
);

const styles = {
  container: { minHeight: '100vh', background: '#f0f3f7', padding: '2rem', fontFamily: 'sans-serif' },
  header: { textAlign: 'center', marginBottom: '2rem' },
  title: { fontSize: '2.5rem', fontWeight: '700', color: '#333' },
  subtitle: { fontSize: '1.2rem', color: '#666', marginBottom: '1rem' },
  searchContainer: { position: 'relative', maxWidth: '500px', margin: '0 auto' },
  searchInput: { width: '100%', padding: '0.75rem 2.5rem 0.75rem 1rem', borderRadius: '25px', border: '1px solid #ccc', outline: 'none', fontSize: '1rem' },
  clearBtn: { position: 'absolute', right: '0.5rem', top: '0.25rem', border: 'none', background: 'transparent', cursor: 'pointer', fontSize: '1rem' },
  cardList: { display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(300px, 1fr))', gap: '1.5rem' },
  card: { display: 'flex', flexDirection: 'column', borderRadius: '16px', overflow: 'hidden', boxShadow: '0 6px 20px rgba(0,0,0,0.1)', cursor: 'pointer', transition: 'transform 0.3s' },
  imageContainer: { height: '180px', backgroundSize: 'cover', backgroundPosition: 'center', position: 'relative' },
  ratingBadge: { position: 'absolute', top: '10px', right: '10px', background: 'rgba(255,255,255,0.9)', padding: '0.25rem 0.5rem', borderRadius: '12px', fontWeight: '600', fontSize: '0.9rem' },
  cardContent: { padding: '1rem', display: 'flex', flexDirection: 'column', gap: '0.5rem' },
  restaurantName: { fontSize: '1.25rem', fontWeight: '700', margin: 0 },
  cuisine: { color: '#667eea', fontWeight: '500' },
  address: { fontSize: '0.9rem', color: '#555' },
  hours: { fontSize: '0.9rem', color: '#555' },
  reserveBtn: { marginTop: 'auto', padding: '0.5rem 1rem', borderRadius: '10px', border: 'none', background: '#764ba2', color: 'white', cursor: 'pointer', fontWeight: '600' },
  loadingContainer: { display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', minHeight: '100vh' },
  spinner: { width: '50px', height: '50px', border: '5px solid #e0e0e0', borderTop: '5px solid #667eea', borderRadius: '50%', animation: 'spin 1s linear infinite' },
  loadingText: { marginTop: '1rem', color: '#333' },
  emptyState: { textAlign: 'center', marginTop: '4rem', color: '#666' },
  emptyIcon: { fontSize: '4rem', display: 'block', marginBottom: '1rem' },
  emptyTitle: { fontSize: '1.8rem', marginBottom: '0.5rem' },
  emptyText: { fontSize: '1rem' }
};

export default RestaurantList;
